from fastapi import FastAPI, Form
from fastapi.testclient import TestClient
from typing import Optional

app = FastAPI()

@app.post("/test")
async def test_endpoint(name: Optional[str] = Form(None)):
    return {"name": name}

client = TestClient(app)

def test_empty_string_as_none():
    # When name is sent as an empty string, it should be interpreted as None if the default is None
    # According to the issue, currently it might be interpreted as "" which then fails validation 
    # if it's supposed to be None, or just stays as "".
    # But the issue says "validation would choke on that empty string".
    # If name: Optional[str] = Form(None), then "" should be treated as None.
    response = client.post("/test", data={"name": ""})
    assert response.status_code == 200
    assert response.json() == {"name": None}

def test_missing_field_as_none():
    response = client.post("/test", data={})
    assert response.status_code == 200
    assert response.json() == {"name": None}

def test_provided_value():
    response = client.post("/test", data={"name": "foo"})
    assert response.status_code == 200
    assert response.json() == {"name": "foo"}

if __name__ == "__main__":
    test_empty_string_as_none()
    test_missing_field_as_none()
    test_provided_value()
    print("All tests passed!")
